from pathlib import Path
import hashlib
import json
import tarfile

root = Path('/source/out/graphics-package/02d-final-linux')
archive = root.parent / 'SharkGraphicsProbe-Ubuntu24-x86_64.tar.gz'
if archive.exists():
    raise ValueError('Fresh archive required')
manifest = json.loads((root / 'package-manifest.json').read_text())
expected = set(manifest['files']) | {'package-manifest.json'}
actual = {p.relative_to(root).as_posix() for p in root.rglob('*') if p.is_file()}
if actual != expected or any(p.is_symlink() for p in root.rglob('*')):
    raise ValueError('Package file set differs from manifest')
with tarfile.open(archive, 'w:gz') as tar:
    for path in sorted(root.rglob('*')):
        name = path.relative_to(root).as_posix()
        info = tar.gettarinfo(str(path), arcname=name)
        info.uid = info.gid = 0
        info.uname = info.gname = ''
        info.mode = 0o755 if path.is_dir() or name == 'bin/GraphicsProbe' else 0o644
        if path.is_file():
            with path.open('rb') as source:
                tar.addfile(info, source)
        else:
            tar.addfile(info)
with tarfile.open(archive) as tar:
    files = {member.name: member for member in tar if member.isfile()}
    if set(files) != expected:
        raise ValueError('Archive file set differs from manifest')
    for name, member in files.items():
        data = tar.extractfile(member).read()
        if hashlib.sha256(data).hexdigest() != hashlib.sha256((root / name).read_bytes()).hexdigest():
            raise ValueError(f'Archive bytes changed: {name}')
record = {'status': 'PASS', 'archive': str(archive), 'bytes': archive.stat().st_size,
          'sha256': hashlib.file_digest(archive.open('rb'), 'sha256').hexdigest(),
          'manifest_payloads': len(manifest['files']), 'archive_files': len(expected),
          'permissions': 'directories and bin/GraphicsProbe 0755; other payloads 0644; UID/GID 0',
          'scope': 'Archive completeness only; no GPU or clean-machine qualification'}
Path('/source/out/02d-final-work/linux-archive.json').write_text(json.dumps(record, indent=2) + '\n')
print(json.dumps(record))

